#!/usr/bin/bash
#
# Serve qwen3-next-80b-a3b-thinking-nvfp4 with vLLM on NVIDIA GB10 (Grace-Blackwell, sm_121).
# Canonical, fully-validated serve config (passed all three gates: works / good / fast).
# AUTO-GENERATED by scripts/gen_launcher.sh from runbooks/nvidia/Qwen3-Next-80B-A3B-Thinking-NVFP4/VLLM-23-nvidia_Qwen3-Next-80B-A3B-Thinking_NVFP4_final.sh — do not hand-edit.
#
# Serves the OpenAI-compatible API on http://0.0.0.0:${PORT:-8000}/v1. Weights load from the host
# HF cache ($HF_HOME or ~/.cache/huggingface); set HF_TOKEN to pull on first run. Runs DETACHED:
#   docker logs -f <NAME>   # follow startup/serving logs    (NAME defaults below)
#   docker rm -f  <NAME>    # stop + remove the container
#   PORT=8001 NAME=foo ./VLLM-23-nvidia_Qwen3-Next-80B-A3B-Thinking_NVFP4.sh   # override the published port / container name
#

# NOTE: this config uses a LOCALLY-BUILT vLLM 0.23.0 image (`vllm-openai:0.23.0-qwen3nextmtp-fix`), not a portable
# upstream digest — it must be built on the host before this launcher will run. See its
# Dockerfile under backends/vllm/images/ and the matching entry in backends/vllm/image.lock.
# Blackwell kernels are sm_120 (forward-compatible to the GB10's sm_121); FlashInfer JITs FP4/MoE.
export VLLM_IMAGE="vllm-openai:0.23.0-qwen3nextmtp-fix"  # 0.23.0
export MODEL="nvidia/Qwen3-Next-80B-A3B-Thinking-NVFP4"
export MODEL_REVISION="2adcdd3e2482cd6fa1676b4f8e6f459a28796f08"   # pinned for reproducibility

# Validated serving context (the benchmark shape). Lower it to raise the guaranteed concurrency
# floor; raise toward the model's native context for long-context serving (KV pool = util below).
export MAX_MODEL_LEN=8192

NAME="${NAME:-vllm-qwen3-next-80b-a3b-thinking-nvfp4}"
PORT="${PORT:-8000}"
HF_CACHE="${HF_HOME:-$HOME/.cache/huggingface}"

# Replace any prior container of this name.
docker rm -f "${NAME}" 2>/dev/null || true

docker run -d --name "${NAME}" \
	--gpus all \
	--ipc=host \
	-p "${PORT}:8000" \
	-v "${HF_CACHE}:/root/.cache/huggingface" \
	-e TOKENIZERS_PARALLELISM=false \
	-e "HF_TOKEN=${HF_TOKEN:-}" \
	"${VLLM_IMAGE}" \
		"${MODEL}" \
		--served-model-name qwen3-next-80b-a3b-thinking-nvfp4 \
		--revision "${MODEL_REVISION}" \
		--max-model-len "${MAX_MODEL_LEN}" \
		--tensor-parallel-size 1 \
		--gpu-memory-utilization 0.5 \
		--speculative-config '{"method":"qwen3_next_mtp","num_speculative_tokens":1}' \
		--override-generation-config '{"temperature":0.6,"top_p":0.95,"top_k":20}' \
		--enable-auto-tool-choice \
		--tool-call-parser hermes \
		--reasoning-parser qwen3
